#include <iostream>
using namespace std;

int main() {
    int rad[5];
    for (int i = 0; i < 5; i++) {
        cin >> rad[i];
    }

    // 1. Maintain hazardous counter (rad[i] > 50)
    // 2. Accumulate total radiation sum
    // 3. Find lowest radiation value (initialize min_rad with rad[0])
    // 4. Print the three metrics:
    //    HAZARDOUS CONTAINERS: count
    //    TOTAL RADIATION: sum
    //    LOWEST RADIATION: min_rad

    return 0;
}

steps.solution:
#include <iostream>
using namespace std;

int main() {
    int rad[5];
    for (int i = 0; i < 5; i++) {
        cin >> rad[i];
    }

    int hazardous = 0;
    int total_rad = 0;
    int min_rad = rad[0];

    for (int i = 0; i < 5; i++) {
        if (rad[i] > 50) {
            hazardous++;
        }
        total_rad += rad[i];
        if (rad[i] < min_rad) {
            min_rad = rad[i];
        }
    }

    cout << "HAZARDOUS CONTAINERS: " << hazardous << endl;
    cout << "TOTAL RADIATION: " << total_rad << endl;
    cout << "LOWEST RADIATION: " << min_rad << endl;

    return 0;
}
